-- Complete schema for an EMPTY database, including V1 and V2.
-- For an existing database, apply only the missing versioned migrations.
-- Reviewed against the dbdiagram export; CPF trigger and FK semantics preserved.
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;

CREATE TABLE "User"
(
    "id"    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nome"  varchar NOT NULL,
    "email" varchar NOT NULL,
    "país"  varchar,
    "cep"   varchar,
    "senha" varchar(255)
);

CREATE UNIQUE INDEX "User_email_normalized_unique"
    ON "User" (lower(trim("email")));

CREATE TABLE "Competencias"
(
    "id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "competencia" varchar NOT NULL
);

CREATE TABLE "VagaCompetencia"
(
    "id_vaga"        integer NOT NULL,
    "id_competencia" integer NOT NULL
);

CREATE TABLE "CandidatoCompetencia"
(
    "id_candidato"   integer NOT NULL,
    "id_competencia" integer NOT NULL
);

CREATE TABLE "Candidate"
(
    "id_candidato"    integer PRIMARY KEY NOT NULL,
    "cpf"             varchar UNIQUE      NOT NULL,
    "sobrenome"       varchar             NOT NULL,
    "data_nascimento" date                NOT NULL,
    "descricao"       varchar             NOT NULL,
    "formacao"        varchar
);

CREATE TABLE "Company"
(
    "id_empresa" integer PRIMARY KEY NOT NULL,
    "cnpj"       varchar UNIQUE      NOT NULL,
    "descricao"  varchar             NOT NULL
);

CREATE TABLE "Recruiter"
(
    "id_recrutador"   integer PRIMARY KEY NOT NULL,
    "id_empresa"      integer NOT NULL,
    "area"            varchar NOT NULL,
    "descricao"       varchar NOT NULL,
    "cpf"             varchar(32) NOT NULL,
    "data_nascimento" date NOT NULL,
    "ativo"           boolean NOT NULL DEFAULT true,
    CONSTRAINT "Recruiter_user_fk"
        FOREIGN KEY ("id_recrutador") REFERENCES "User" ("id"),
    CONSTRAINT "Recruiter_company_fk"
        FOREIGN KEY ("id_empresa") REFERENCES "Company" ("id_empresa"),
    CONSTRAINT "Recruiter_cpf_format_ck"
        CHECK ("cpf" ~ '^[0-9]{11}$')
);

CREATE UNIQUE INDEX "Recruiter_cpf_normalized_unique"
    ON "Recruiter" ("cpf");

CREATE TABLE "Vaga"
(
    "id"              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "id_empresa"      integer NOT NULL,
    "titulo"          varchar NOT NULL,
    "descricao"       varchar NOT NULL,
    "local_vaga"      varchar NOT NULL
);

CREATE TABLE "Curtida"
(
    "id_candidato"      integer,
    "id_vaga"           integer,
    "curtida_candidato" boolean NOT NULL DEFAULT false,
    "curtida_empresa"   boolean NOT NULL DEFAULT false,
    "data_match"        timestamp,
    "id_recrutador_autor" integer,
    PRIMARY KEY ("id_candidato", "id_vaga")
);

COMMENT ON COLUMN "User"."senha" IS 'Armazenar somente o hash da senha; limites validados pela aplicação conforme o perfil.';
COMMENT ON COLUMN "Recruiter"."cpf" IS 'Normalizado por trigger para 11 dígitos.';
COMMENT ON COLUMN "Curtida"."id_recrutador_autor" IS 'Opcional; primeira autoria do recrutador, quando aplicável.';
COMMENT ON TABLE "Curtida" IS 'O match ocorre quando as duas flags de curtida são verdadeiras.';

ALTER TABLE "VagaCompetencia"
    ADD FOREIGN KEY ("id_vaga") REFERENCES "Vaga" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "VagaCompetencia"
    ADD FOREIGN KEY ("id_competencia") REFERENCES "Competencias" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "CandidatoCompetencia"
    ADD FOREIGN KEY ("id_candidato") REFERENCES "Candidate" ("id_candidato") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "CandidatoCompetencia"
    ADD FOREIGN KEY ("id_competencia") REFERENCES "Competencias" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Candidate"
    ADD FOREIGN KEY ("id_candidato") REFERENCES "User" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Company"
    ADD FOREIGN KEY ("id_empresa") REFERENCES "User" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Vaga"
    ADD FOREIGN KEY ("id_empresa") REFERENCES "Company" ("id_empresa") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Curtida"
    ADD FOREIGN KEY ("id_candidato") REFERENCES "Candidate" ("id_candidato") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Curtida"
    ADD FOREIGN KEY ("id_vaga") REFERENCES "Vaga" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Curtida"
    ADD CONSTRAINT "Curtida_recruiter_author_fk"
        FOREIGN KEY ("id_recrutador_autor") REFERENCES "Recruiter" ("id_recrutador");

CREATE OR REPLACE FUNCTION recruiter_normalize_cpf()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW."cpf" !~ '^[0-9 .()-]+$' THEN
        RAISE EXCEPTION 'CPF must contain only digits and formatting characters';
    END IF;
    NEW."cpf" := regexp_replace(NEW."cpf", '[^0-9]', '', 'g');
    RETURN NEW;
END;
$$;

CREATE TRIGGER "Recruiter_cpf_normalize_trigger"
BEFORE INSERT OR UPDATE OF "cpf" ON "Recruiter"
FOR EACH ROW
EXECUTE FUNCTION recruiter_normalize_cpf();
